--
-- Name: v_mxx_admin_role; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_mxx_admin_role AS
 SELECT a.id AS admin_id,
    a.user_name,
    a.nick_name,
    r.id AS role_id,
    r.role_name,
    r.role_key,
    r.data_scope
   FROM ((public.mxx_system_admin a
     LEFT JOIN public.mxx_system_admin_role_merge arm ON ((a.id = arm.admin_id)))
     LEFT JOIN public.mxx_system_role r ON ((arm.role_id = r.id)))
  WHERE ((a.deleted = 0) AND ((r.deleted = 0) OR (r.deleted IS NULL)));


--
-- Name: v_mxx_role_menu; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_mxx_role_menu AS
 SELECT r.id AS role_id,
    r.role_name,
    m.id AS menu_id,
    m.name AS menu_name,
    m.path,
    m.type,
    m.perm
   FROM ((public.mxx_system_role r
     LEFT JOIN public.mxx_system_role_menu_merge rmm ON ((r.id = rmm.role_id)))
     LEFT JOIN public.mxx_system_menu m ON ((rmm.menu_id = m.id)))
  WHERE ((r.deleted = 0) AND ((m.status = 0) OR (m.status IS NULL)));


--
-- Name: v_mxx_system_admin; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_mxx_system_admin AS
 SELECT a.id,
    a.user_name,
    a.nick_name,
    a.user_type,
    a.email,
    a.mobile,
    a.gender,
    a.avatar,
    a.password,
    a.status,
    a.deleted,
    a.login_ip,
    a.login_date,
    a.create_by,
    a.create_time,
    a.update_by,
    a.update_time,
    a.remark,
    a.sort,
    COALESCE(r.role_name, ''::character varying) AS role_name,
    COALESCE(d.dept_name, ''::character varying) AS dept_name
   FROM ((((public.mxx_system_admin a
     LEFT JOIN public.mxx_system_admin_role_merge arm ON ((a.id = arm.admin_id)))
     LEFT JOIN public.mxx_system_role r ON ((arm.role_id = r.id)))
     LEFT JOIN public.mxx_system_admin_dept_merge adm ON ((a.id = adm.admin_id)))
     LEFT JOIN public.mxx_system_dept d ON ((adm.dept_id = d.id)))
  WHERE (a.deleted = 0);


